/**
 * The vault's chat manifest (nl-runtime `ChatManifest`). M2: generated by
 * `npx nl-generate` into `chat-manifest/` at the vault root, from the specs,
 * reducers, barrels and `chat.overrides.ts`.
 *
 * M5: the sheet (components/ChatSheet.tsx) takes `VAULT_SHEET_MANIFEST`,
 * the vault's models plus nl-drive's document-drive extension (its seven
 * ops on the `client` executor), so drive-level requests have ops.
 * `VAULT_MANIFEST` stays the vault's models only (parity, the equality test).
 */
import type { ChatManifest } from "nl-runtime";
import { mergeChatManifests, withExtensions } from "nl-manifest";
import { compileDocumentDriveManifest, DRIVE_DOCUMENT_TYPE } from "nl-drive";
import { chatApp, chatManifest } from "../../../chat-manifest/index.js";

export const VAULT_MANIFEST: ChatManifest = chatManifest;

const merged = mergeChatManifests(withExtensions(chatApp, compileDocumentDriveManifest()));

/** The vault's manifest with the document-drive ops; the drive's type reads "drive". */
export const VAULT_SHEET_MANIFEST: ChatManifest = {
  ...merged,
  typeLabels: { ...merged.typeLabels, [DRIVE_DOCUMENT_TYPE]: "drive" },
};

/**
 * What ADD_FILE may create (step 2's document-type candidates): the
 * types the vault's New menu creates, in its words.
 */
export const VAULT_DOCUMENT_TYPES: readonly { id: string; label: string }[] = [
  { id: "bai/knowledge-note", label: "Knowledge note" },
  { id: "bai/moc", label: "Map of Content (MOC)" },
  { id: "bai/source", label: "Source" },
  { id: "bai/project", label: "Project" },
  { id: "bai/wbs", label: "Plan (WBS)" },
  { id: "bai/observation", label: "Observation" },
  { id: "bai/tension", label: "Tension" },
  { id: "bai/research-claim", label: "Research claim" },
  { id: "bai/health-report", label: "Health report" },
];
